const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const CATEGORY={content:'素材与内容',generation:'生成',transform:'处理与转换',agent:'插件与 Agent',control:'流程控制',quality:'校验与人工',output:'结果与交付'};
