function renderTemplates(){examples.workflows.forEach(w=>$('#template-select').add(new Option(w.title,w.id)))}
function renderCatalog(filter='',pluginOnly=false){const root=$('#catalog');root.innerHTML='';const groups={};catalog.definitions.filter(x=>(!pluginOnly||x.source==='plugin'||x.category==='agent')&&(x.title.toLowerCase().includes(filter.toLowerCase())||x.id.includes(filter.toLowerCase())||x.description?.includes(filter))).forEach(x=>(groups[x.category]??=[]).push(x));Object.entries(groups).forEach(([cat,items])=>{const s=document.createElement('section');s.className='catalog-group';s.innerHTML=`<label>${CATEGORY[cat]||cat}</label>`;items.forEach(x=>{const b=document.createElement('button');b.className='catalog-item';b.draggable=true;b.innerHTML=`<i>${ICON[x.category]||'◇'}</i><div><b>${x.title}</b><small>${x.description||`${x.inputs.length} 输入 · ${x.outputs.length} 输出`}</small><em>${x.source==='plugin'?'PLUGIN · ':''}${x.inputs.length} IN · ${x.outputs.length} OUT</em></div><span>＋</span>`;b.ondragstart=e=>e.dataTransfer.setData('definitionId',x.id);b.ondblclick=()=>addNode(x.id,{x:350,y:220});s.append(b)});root.append(s)})}
function renderTemplateCards(){const root=$('#catalog');root.innerHTML='<section class="catalog-group"><label>业务组合模板</label></section>';const section=root.firstElementChild;examples.workflows.forEach(w=>{const b=document.createElement('button');b.className='catalog-item template-item';b.innerHTML=`<i>⌁</i><div><b>${w.title}</b><small>${w.nodes.length} 个节点 · ${w.edges.length} 条连线</small><em>包含 Validator 与 Gate</em></div><span>载入</span>`;b.onclick=()=>loadWorkflow(w);section.append(b)})}
function setLibraryView(view){libraryView=view;$$('[data-library-view]').forEach(b=>b.classList.toggle('active',b.dataset.libraryView===view));$('#template-block').hidden=view!=='templates';$('#plugin-tools').hidden=view!=='plugins';if(view==='templates')renderTemplateCards();else renderCatalog($('#node-search').value,view==='plugins')}
function loadWorkflow(w,withCheckpoint=true){if(withCheckpoint)checkpoint();nodes=structuredClone(w.nodes);edges=structuredClone(w.edges);groups=[];clearSelection();$('#workflow-title').textContent=w.title;render();markDirty();setTimeout(fitView,20)}
function addNode(definitionId,position){if(mode!=='design')return null;checkpoint();const id=`node-${Date.now().toString(36)}`;nodes.push({id,definitionId,position,config:{}});setSelection([id]);render();showInspector();toast(`已添加「${def(definitionId).title}」`);return id}
function deleteNode(id){setSelection([id]);deleteSelectedNodes()}
function duplicateNode(id){setSelection([id]);duplicateSelectedNodes()}
function deleteSelectedNodes(){if(mode!=='design')return toast('当前模式已锁定拓扑，请切换到设计模式',true);const ids=new Set(selectedIds);if(!ids.size)return;checkpoint();nodes=nodes.filter(n=>!ids.has(n.id));edges=edges.filter(e=>!ids.has(e.source)&&!ids.has(e.target));groups=groups.map(g=>({...g,memberIds:g.memberIds.filter(id=>!ids.has(id))})).filter(g=>g.memberIds.length);clearSelection();render();showInspector();toast(`已删除 ${ids.size} 个节点，可撤销`)}
function duplicateSelectedNodes(){if(mode!=='design')return toast('当前模式已锁定拓扑，请切换到设计模式',true);if(!selectedIds.size)return;checkpoint();const idMap=new Map(),copies=[];for(const n of nodes.filter(x=>selectedIds.has(x.id))){const copy=structuredClone(n);copy.id=`node-${Date.now().toString(36)}-${copies.length}`;copy.position={x:n.position.x+34,y:n.position.y+34};idMap.set(n.id,copy.id);copies.push(copy)}const copiedEdges=edges.filter(e=>idMap.has(e.source)&&idMap.has(e.target)).map((e,i)=>({...structuredClone(e),id:`edge-${Date.now().toString(36)}-${i}`,source:idMap.get(e.source),target:idMap.get(e.target)}));nodes.push(...copies);edges.push(...copiedEdges);setSelection(copies.map(n=>n.id));render();showInspector();toast(`已复制 ${copies.length} 个节点`)}

function render(){renderGroups();renderNodes();renderEdges();tagRenderedEdges();$('#node-count').textContent=`${nodes.length} 节点`;$('#edge-count').textContent=`${edges.length} 连线`;$('#empty-state').hidden=nodes.length>0;applyTransform();renderMinimap()}
function collapsedNodeIds(){return new Set(groups.filter(g=>g.collapsed).flatMap(g=>g.memberIds))}
function renderGroups(){const root=$('#groups');root.innerHTML='';groups.forEach(g=>{const members=nodes.filter(n=>g.memberIds.includes(n.id));if(!members.length)return;const minX=Math.min(...members.map(n=>n.position.x))-28,minY=Math.min(...members.map(n=>n.position.y))-52,maxX=Math.max(...members.map(n=>n.position.x+286))+28,maxY=Math.max(...members.map(n=>n.position.y+220))+28;const el=document.createElement('section');el.className=`canvas-group ${g.collapsed?'collapsed':''}`;el.dataset.groupId=g.id;el.style.left=`${minX}px`;el.style.top=`${minY}px`;el.style.width=`${maxX-minX}px`;el.style.height=`${g.collapsed?42:maxY-minY}px`;el.innerHTML=`<header><b>${g.title}</b><div><button data-group="collapse" title="折叠/展开">${g.collapsed?'＋':'−'}</button><button data-group="remove" title="取消分组">×</button></div></header>`;el.querySelector('[data-group=collapse]').onclick=e=>{e.stopPropagation();checkpoint();g.collapsed=!g.collapsed;render();markDirty()};el.querySelector('[data-group=remove]').onclick=e=>{e.stopPropagation();checkpoint();groups=groups.filter(x=>x.id!==g.id);render();markDirty()};el.querySelector('header').onpointerdown=e=>{if(e.target.closest('button')||mode!=='design')return;startGroupDrag(e,g)};root.append(el)})}
function renderNodes(){renderMetrics.fullNodeRenders++;document.body.dataset.fullNodeRenders=String(renderMetrics.fullNodeRenders);const root=$('#nodes');root.innerHTML='';const hidden=collapsedNodeIds();nodes.forEach(n=>{if(hidden.has(n.id))return;const d=def(n.definitionId);if(!d)return;const incoming=edges.filter(e=>e.target===n.id&&!e.disabled);const missing=n.disabled?[]:d.inputs.filter(p=>p.required&&!incoming.some(e=>e.targetPort===p.id)&&n.config?.[p.id]===undefined);const el=document.createElement('article');el.className=`canvas-node ${selected?.type==='node'&&selected.id===n.id?'selected':''} ${missing.length?'blocked':''} ${n.disabled?'disabled':''}`;el.dataset.id=n.id;el.style.left=`${n.position.x}px`;el.style.top=`${n.position.y}px`;
    const preview=hasMediaPreview(d)?`<div class="node-preview">${PREVIEWS.slice(0,d.category==='output'?4:3).map(src=>`<img src="${src}">`).join('')}<i>+${d.category==='output'?8:1}</i></div>`:'';
    el.innerHTML=`<header class="node-head"><div><small>${d.category.toUpperCase()} · ${d.version}</small><b>${d.title}</b></div><span class="node-status">${n.disabled?'DISABLED':missing.length?'待配置':'READY'}</span></header><div class="node-body">${d.inputs.map(p=>portRow(n,p,'input')).join('')}${preview}<div class="node-summary">${n.disabled?'当前节点与关联连线不参与运行':summary(n,d,missing)}</div>${d.outputs.map(p=>portRow(n,p,'output')).join('')}</div><footer class="node-foot"><span>#${n.id.slice(-7)}</span><button data-action="inspect">配置</button></footer>`;
    el.classList.toggle('multi-selected',selectedIds.has(n.id)&&selectedIds.size>1);el.onpointerdown=e=>{if(e.target.closest('.port')||e.target.closest('button, input, select, textarea'))return;const additive=e.shiftKey||e.metaKey||e.ctrlKey;if(additive||!selectedIds.has(n.id))selectNode(n.id,additive);if(mode==='design'&&selectedIds.has(n.id))startNodeDrag(e,n)};el.oncontextmenu=e=>{e.preventDefault();if(!selectedIds.has(n.id))selectNode(n.id);showContext(e.clientX,e.clientY,selectedIds.size>1?'multi':'node',n.id)};el.ondblclick=e=>{if(!e.target.closest('.port')){selectNode(n.id);showInspector()}};el.querySelector('[data-action=inspect]').onclick=()=>{selectNode(n.id);showInspector()};$$('.port',el).forEach(p=>{if(p.dataset.direction==='output')p.onpointerdown=e=>reconnectEdge?.end==='source'?handlePort(n.id,p.dataset.port,'output'):startPortDrag(e,n.id,p.dataset.port);else p.onclick=e=>{e.stopPropagation();handlePort(n.id,p.dataset.port,p.dataset.direction)}});root.append(el)})}
function portRow(n,p,direction){let state='';if(direction==='input'&&(connectionDrag||reconnectEdge?.end==='target')){const source=connectionDrag||reconnectSource();state=source?.nodeId===n.id||!compatible(source?.port.type,p.type)?'is-incompatible':'is-compatible'}if(direction==='output'&&reconnectEdge?.end==='source'){const target=reconnectTarget();state=target?.nodeId===n.id||!compatible(p.type,target?.port.type)?'is-incompatible':'is-compatible'}return `<div class="port-row ${direction}">${direction==='input'?`<button class="port input ${state}" data-node="${n.id}" data-port="${p.id}" data-direction="input" title="${p.type}"></button>`:''}<span class="port-label"><b>${p.id}${p.required?' *':''}</b><em>${p.type} · ${p.cardinality}</em></span>${direction==='output'?`<button class="port output ${state}" data-node="${n.id}" data-port="${p.id}" data-direction="output" title="${p.type}"></button>`:''}</div>`}
function hasMediaPreview(d){return d.category==='generation'||d.category==='agent'||d.category==='output'||['content.image','content.image-collection','content.video'].includes(d.id)}
function summary(n,d,missing){if(missing.length)return `缺少：${missing.map(x=>x.id).join('、')}`;if(d.category==='generation')return `${n.config.aspectRatio||'16:9'} · ${n.config.count||1} 个候选`;if(['content.image','content.image-collection','content.video'].includes(d.id))return `${n.config.assetRefs?.length||(n.config.assetRef?1:0)} 项已绑定资产`;if(d.category==='agent')return `${d.source==='plugin'?'已发布插件':'Agent'} · ${n.config.operation||'run'}`;if(d.category==='quality')return '等待报告或人工结论';return d.executorRef||'本地内容 / 结果视图'}
function edgePath(s,t){const dx=Math.max(70,(t.x-s.x)*.45);return `M ${s.x} ${s.y} C ${s.x+dx} ${s.y}, ${t.x-dx} ${t.y}, ${t.x} ${t.y}`}
function renderEdges(){renderMetrics.fullEdgeRenders++;document.body.dataset.fullEdgeRenders=String(renderMetrics.fullEdgeRenders);const svg=$('#edges'),hidden=collapsedNodeIds();svg.innerHTML='';edges.forEach(e=>{if(hidden.has(e.source)||hidden.has(e.target))return;const s=nodePortPoint(e.source,e.sourcePort,'output'),t=nodePortPoint(e.target,e.targetPort,'input');if(!s||!t)return;const endpointDisabled=nodes.find(n=>n.id===e.source)?.disabled||nodes.find(n=>n.id===e.target)?.disabled,selectEdge=()=>{selectedIds.clear();selected={type:'edge',id:e.id};inspectorTab='mapping';render();showInspector()},openEdgeMenu=ev=>{ev.preventDefault();showContext(ev.clientX,ev.clientY,'edge',e.id)};const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',edgePath(s,t));p.setAttribute('class',`edge ${selected?.type==='edge'&&selected.id===e.id?'active':''} ${e.disabled||endpointDisabled?'disabled':''}`);svg.append(p);const hit=document.createElementNS('http://www.w3.org/2000/svg','path');hit.setAttribute('d',edgePath(s,t));hit.setAttribute('class','edge-hit');hit.onclick=selectEdge;hit.oncontextmenu=openEdgeMenu;svg.append(hit)});if(connectionDrag){const s=nodePortPoint(connectionDrag.nodeId,connectionDrag.portId,'output');if(s){const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',edgePath(s,connectionDrag.pointer));p.setAttribute('class','edge preview');svg.append(p)}}}
function nodePortPoint(nodeId,portId,direction){const n=nodes.find(x=>x.id===nodeId),d=n&&def(n.definitionId);if(!n||!d)return null;const nodeEl=$(`.canvas-node[data-id="${nodeId}"]`),portEl=nodeEl&&$$('.port',nodeEl).find(p=>p.dataset.port===portId&&p.dataset.direction===direction),vp=$('#canvas-viewport');if(portEl&&vp){const r=portEl.getBoundingClientRect(),vr=vp.getBoundingClientRect();return{x:(r.left+r.width/2-vr.left-pan.x)/scale,y:(r.top+r.height/2-vr.top-pan.y)/scale}}const ports=direction==='input'?d.inputs:d.outputs,idx=ports.findIndex(p=>p.id===portId),inputHeight=d.inputs.length*28,preview=hasMediaPreview(d)?54:0,y=n.position.y+58+11+(direction==='input'?idx*28+14:inputHeight+preview+31+idx*28+14);return{x:n.position.x+(direction==='output'?286:0),y}}

function tagRenderedEdges(){const hidden=collapsedNodeIds(),rendered=edges.filter(e=>!hidden.has(e.source)&&!hidden.has(e.target)&&nodePortPoint(e.source,e.sourcePort,'output')&&nodePortPoint(e.target,e.targetPort,'input')),paths=$$('#edges path:not(.preview)');rendered.forEach((edge,index)=>{paths[index*2]?.setAttribute('data-edge-id',edge.id);paths[index*2+1]?.setAttribute('data-edge-id',edge.id)})}
function updateNodeElements(ids){for(const id of ids){const n=nodes.find(x=>x.id===id),el=$(`.canvas-node[data-id="${id}"]`);if(n&&el){el.style.left=`${n.position.x}px`;el.style.top=`${n.position.y}px`}}}
function updateConnectedEdges(ids){const touched=new Set(edges.filter(e=>ids.has(e.source)||ids.has(e.target)).map(e=>e.id));for(const id of touched){const edge=edges.find(e=>e.id===id),s=edge&&nodePortPoint(edge.source,edge.sourcePort,'output'),t=edge&&nodePortPoint(edge.target,edge.targetPort,'input');if(!s||!t)continue;$$(`#edges [data-edge-id="${id}"]`).forEach(path=>path.setAttribute('d',edgePath(s,t)))}}
