function groupGeometry(g){const members=nodes.filter(n=>g.memberIds.includes(n.id));if(!members.length)return null;const minX=Math.min(...members.map(n=>n.position.x))-28,minY=Math.min(...members.map(n=>n.position.y))-52,maxX=Math.max(...members.map(n=>n.position.x+286))+28,maxY=Math.max(...members.map(n=>n.position.y+nodeVisualHeight(n.id)))+28;return{x:minX,y:minY,w:maxX-minX,h:g.collapsed?42:maxY-minY}}
function updateGroupElement(g){const el=$(`.canvas-group[data-group-id="${g.id}"]`),box=groupGeometry(g);if(!el||!box)return;el.style.left=`${box.x}px`;el.style.top=`${box.y}px`;el.style.width=`${box.w}px`;el.style.height=`${box.h}px`}
function scheduleMinimapRender(){if(scheduleMinimapRender.frame)return;scheduleMinimapRender.frame=requestAnimationFrame(()=>{scheduleMinimapRender.frame=0;renderMinimap()})}
function handlePort(nodeId,portId,direction){if(mode!=='design')return toast('运行或审阅模式下不能修改连线');const node=nodes.find(n=>n.id===nodeId),d=def(node.definitionId),port=(direction==='input'?d.inputs:d.outputs).find(p=>p.id===portId);if(reconnectEdge)return finishReconnect({nodeId,portId,port,direction});if(!pendingPort){if(direction!=='output')return toast('请先选择一个输出端口',true);pendingPort={nodeId,portId,port};render();toast(`请选择兼容的 ${port.type} 输入端口`);return}if(direction!=='input'){pendingPort={nodeId,portId,port};return}connectPorts(pendingPort,{nodeId,portId,port});pendingPort=null}
function connectPorts(source,target){if(!compatible(source.port.type,target.port.type))return toast(`类型不兼容：${source.port.type} → ${target.port.type}`,true);if(target.port.cardinality==='one'&&edges.some(e=>e.target===target.nodeId&&e.targetPort===target.portId))return toast('该单值端口已经连接',true);if(source.nodeId===target.nodeId)return toast('不能连接节点自身',true);checkpoint();edges.push({id:`edge-${Date.now().toString(36)}`,source:source.nodeId,sourcePort:source.portId,target:target.nodeId,targetPort:target.portId});render();toast('连线已创建')}
