function compatible(a,b){return a===b||b==='artifact.any'}

function clearSelection(){selected=null;selectedIds.clear();pendingPort=null}
function setSelection(ids){selectedIds=new Set(ids);selected=ids.length===1?{type:'node',id:ids[0]}:ids.length>1?{type:'multi'}:null;inspectorTab='config'}
function selectNode(id,additive=false){if(additive){const ids=new Set(selectedIds);ids.has(id)?ids.delete(id):ids.add(id);setSelection([...ids])}else setSelection([id]);render();showInspector()}
function showInspectorLegacy(){const root=$('#inspector');root.classList.toggle('open',Boolean(selected));if(!selected){root.innerHTML='<div class="inspector-empty"><span>◇</span><b>选择一个节点或连线</b><p>在此配置端口、参数、资产、运行与版本。</p></div>';return}if(selected.type==='edge'){const e=edges.find(x=>x.id===selected.id);const s=def(nodes.find(n=>n.id===e.source).definitionId).outputs.find(p=>p.id===e.sourcePort);root.innerHTML=`<div class="inspector-head"><div><small>TYPED EDGE</small><b>数据连线</b></div><button id="close-inspector">×</button></div><div class="inspector-tabs"><button class="active">映射</button><button disabled>问题</button><button disabled>历史</button></div><div class="inspector-body"><section class="detail-card"><h4>数据契约</h4><div class="port-inspector"><div><span>来源</span><code>${e.source}.${e.sourcePort}</code></div><div><span>目标</span><code>${e.target}.${e.targetPort}</code></div><div><span>类型</span><code>${s.type}</code></div></div></section><button id="delete-edge" class="wide" ${mode==='design'?'':'disabled'}>删除连线</button></div>`;$('#close-inspector').onclick=()=>{selected=null;render();showInspector()};$('#delete-edge').onclick=()=>{if(mode!=='design')return;checkpoint();edges=edges.filter(x=>x.id!==e.id);selected=null;render();showInspector()};return}
  const n=nodes.find(x=>x.id===selected.id),d=def(n.definitionId);root.innerHTML=`<div class="inspector-head"><div><small>${d.category.toUpperCase()} · ${d.id}</small><b>${d.title}</b></div><button id="close-inspector">×</button></div><div class="inspector-tabs"><button class="active">配置</button><button disabled>输入</button><button disabled>输出</button><button disabled>运行</button><button disabled>问题</button><button disabled>历史</button></div><div class="inspector-body"><section class="detail-card"><h4>节点定义</h4><p>${d.description||''}</p><div class="port-inspector"><div><span>版本</span><code>${d.version}</code></div><div><span>执行器</span><code>${d.executorRef||'无'}</code></div></div></section>${configFields(n,d)}<section class="detail-card"><h4>端口契约</h4><div class="port-inspector">${d.inputs.map(p=>`<div><span>← ${p.id}${p.required?' *':''}</span><code>${p.type}</code></div>`).join('')}${d.outputs.map(p=>`<div><span>→ ${p.id}</span><code>${p.type}</code></div>`).join('')}</div></section>${hasMediaPreview(d)&&d.category!=='output'?`<div class="asset-strip">${PREVIEWS.map(x=>`<img src="${x}">`).join('')}</div><button id="open-assets" class="wide">添加与预览多资产</button>`:''}</div>`;$('#close-inspector').onclick=()=>{selected=null;render();showInspector()};$('#open-assets')?.addEventListener('click',openAssets);$$('[data-config]',root).forEach(input=>{input.disabled=mode!=='design';input.onchange=()=>{if(mode!=='design')return;checkpoint();n.config[input.dataset.config]=input.type==='number'?Number(input.value):input.value;render();showInspector()}})}
function configFields(n,d){if(['content.prompt','content.text'].includes(d.id))return `<div class="field"><label>文本内容</label><textarea data-config="value">${n.config.value||''}</textarea></div>`;if(d.category==='generation')return `<div class="field"><label>宽高比</label><select data-config="aspectRatio"><option>16:9</option><option>9:16</option><option>1:1</option></select></div><div class="field"><label>生成数量</label><input data-config="count" type="number" min="1" max="8" value="${n.config.count||1}"></div><div class="field"><label>时长（视频节点）</label><input data-config="durationSeconds" type="number" min="1" max="20" value="${n.config.durationSeconds||5}"></div>`;if(d.category==='agent')return `<div class="field"><label>已发布 Plugin</label><input value="${d.id}@${d.version}" readonly></div><div class="field"><label>Operation</label><input data-config="operation" value="${n.config.operation||'generate'}"></div>`;return ''}

function inspectorTabs(items){return `<div class="inspector-tabs">${items.map(([id,label])=>`<button data-inspector-tab="${id}" class="${inspectorTab===id?'active':''}">${label}</button>`).join('')}</div>`}
function nodeInspectorContent(n,d){const incoming=edges.filter(e=>e.target===n.id),outgoing=edges.filter(e=>e.source===n.id);if(inspectorTab==='inputs')return `<section class="detail-card"><h4>输入快照</h4><div class="port-inspector">${d.inputs.map(p=>{const links=incoming.filter(e=>e.targetPort===p.id);return `<div><span>← ${p.id}${p.required?' *':''}</span><code>${links.length?`${links.length} 条 · ${p.type}`:`未连接 · ${p.type}`}</code></div>`}).join('')||'<p>该节点没有输入端口。</p>'}</div></section>`;if(inspectorTab==='outputs')return `<section class="detail-card"><h4>输出与下游</h4><div class="port-inspector">${d.outputs.map(p=>{const links=outgoing.filter(e=>e.sourcePort===p.id);return `<div><span>→ ${p.id}</span><code>${links.length} 个下游 · ${p.type}</code></div>`}).join('')||'<p>该节点没有输出端口。</p>'}</div></section>`;if(inspectorTab==='run')return `<section class="detail-card"><h4>执行路由</h4><p>当前只创建模拟 NodeRun，不调用真实模型。</p><div class="port-inspector"><div><span>执行器</span><code>${d.executorRef||'本地节点'}</code></div><div><span>执行范围</span><code>当前节点及必要上游</code></div></div></section><button id="run-inspected" class="wide primary">预检并运行此节点</button>`;if(inspectorTab==='issues'){const missing=d.inputs.filter(p=>p.required&&!incoming.some(e=>e.targetPort===p.id)&&n.config?.[p.id]===undefined);return `<section class="detail-card"><h4>节点问题</h4>${missing.length?missing.map(p=>`<p>⚠ 缺少必填输入 <code>${p.id}</code></p>`).join(''):'<p>✓ 当前节点未发现阻塞问题。</p>'}</section>`}if(inspectorTab==='history')return `<section class="detail-card"><h4>版本与变更</h4><div class="port-inspector"><div><span>NodeDefinition</span><code>${d.version}</code></div><div><span>画布状态</span><code>${dirty?'本地草稿未保存':'已保存'}</code></div><div><span>运行历史</span><code>尚无持久化运行</code></div></div></section>`;return `<section class="detail-card"><h4>节点定义</h4><p>${d.description||''}</p><div class="port-inspector"><div><span>版本</span><code>${d.version}</code></div><div><span>执行器</span><code>${d.executorRef||'无'}</code></div></div></section>${configFields(n,d)}${hasMediaPreview(d)&&d.category!=='output'?`<div class="asset-strip">${PREVIEWS.map(x=>`<img src="${x}">`).join('')}</div><button id="open-assets" class="wide">添加与预览多资产</button>`:''}`}
function showInspector(){const root=$('#inspector');root.classList.toggle('open',Boolean(selected));if(!selected){root.innerHTML='<div class="inspector-empty"><span>◇</span><b>选择一个节点或连线</b><p>在此配置端口、参数、资产、运行与版本。</p></div>';return}if(selected.type==='multi'){root.innerHTML=`<div class="inspector-head"><div><small>MULTI SELECTION</small><b>已选择 ${selectedIds.size} 个节点</b></div><button id="close-inspector">×</button></div><div class="inspector-body multi-inspector"><section class="detail-card"><h4>批量操作</h4><p>可整体拖动、分组、禁用、复制或删除；复制时保留内部连线。</p></section><div class="multi-actions"><button id="duplicate-selected">复制所选</button><button id="toggle-disabled">启用／禁用</button><button id="group-selected">创建分组</button><button id="align-selected">顶端对齐</button><button id="layout-selected">拓扑布局</button><button id="delete-selected">删除所选</button></div></div>`;$('#duplicate-selected').onclick=duplicateSelectedNodes;$('#delete-selected').onclick=deleteSelectedNodes;$('#toggle-disabled').onclick=toggleSelectedDisabled;$('#group-selected').onclick=createGroupFromSelection;$('#align-selected').onclick=alignSelectedTop;$('#layout-selected').onclick=autoLayout;$('#close-inspector').onclick=()=>{clearSelection();render();showInspector()};return}if(selected.type==='edge'){const e=edges.find(x=>x.id===selected.id);if(!e){clearSelection();return showInspector()}const sourceNode=nodes.find(n=>n.id===e.source),s=def(sourceNode.definitionId).outputs.find(p=>p.id===e.sourcePort);const tabs=[['mapping','映射'],['issues','问题'],['history','历史']];let content=inspectorTab==='issues'?`<section class="detail-card"><h4>连线问题</h4><p>✓ 来源与目标端口类型兼容。</p></section>`:inspectorTab==='history'?`<section class="detail-card"><h4>连线历史</h4><p>本地草稿连线，尚未生成版本记录。</p></section>`:`<section class="detail-card"><h4>数据契约</h4><div class="port-inspector"><div><span>来源</span><code>${e.source}.${e.sourcePort}</code></div><div><span>目标</span><code>${e.target}.${e.targetPort}</code></div><div><span>类型</span><code>${s.type}</code></div></div></section><div class="multi-actions"><button id="reconnect-source">重接来源</button><button id="reconnect-target">重接目标</button></div><button id="delete-edge" class="wide" ${mode==='design'?'':'disabled'}>删除连线</button>`;root.innerHTML=`<div class="inspector-head"><div><small>TYPED EDGE</small><b>数据连线</b></div><button id="close-inspector">×</button></div>${inspectorTabs(tabs)}<div class="inspector-body">${content}</div>`;bindInspectorTabs();$('#close-inspector').onclick=()=>{clearSelection();render();showInspector()};$('#reconnect-source')?.addEventListener('click',()=>beginReconnect(e.id,'source'));$('#reconnect-target')?.addEventListener('click',()=>beginReconnect(e.id,'target'));$('#delete-edge')?.addEventListener('click',()=>{checkpoint();edges=edges.filter(x=>x.id!==e.id);clearSelection();render();showInspector()});return}const n=nodes.find(x=>x.id===selected.id);if(!n){clearSelection();return showInspector()}const d=def(n.definitionId),tabs=[['config','配置'],['inputs','输入'],['outputs','输出'],['run','运行'],['issues','问题'],['history','历史']];root.innerHTML=`<div class="inspector-head"><div><small>${d.category.toUpperCase()} · ${d.id}</small><b>${d.title}</b></div><button id="close-inspector">×</button></div>${inspectorTabs(tabs)}<div class="inspector-body">${nodeInspectorContent(n,d)}${inspectorTab==='config'?`<button id="toggle-node-disabled" class="wide">${n.disabled?'启用节点':'禁用节点'}</button>`:''}</div>`;bindInspectorTabs();$('#close-inspector').onclick=()=>{clearSelection();render();showInspector()};$('#open-assets')?.addEventListener('click',openAssets);$('#run-inspected')?.addEventListener('click',()=>startRun(true));$('#toggle-node-disabled')?.addEventListener('click',toggleSelectedDisabled);$$('[data-config]',root).forEach(input=>{input.disabled=mode!=='design';input.onchange=()=>{checkpoint();n.config[input.dataset.config]=input.type==='number'?Number(input.value):input.value;render();showInspector()}})}
function bindInspectorTabs(){$$('[data-inspector-tab]').forEach(b=>b.onclick=()=>{inspectorTab=b.dataset.inspectorTab;showInspector()})}
function alignSelectedTop(){if(selectedIds.size<2)return;checkpoint();const selectedNodes=nodes.filter(n=>selectedIds.has(n.id)),top=Math.min(...selectedNodes.map(n=>n.position.y));selectedNodes.forEach(n=>n.position.y=top);render();showInspector();markDirty()}
function createGroupFromSelection(){if(mode!=='design'||selectedIds.size<2)return toast('请先选择至少两个节点',true);checkpoint();const memberIds=[...selectedIds];groups=groups.map(g=>({...g,memberIds:g.memberIds.filter(id=>!selectedIds.has(id))})).filter(g=>g.memberIds.length);groups.push({id:`group-${Date.now().toString(36)}`,title:`节点组 ${groups.length+1}`,memberIds,collapsed:false});render();showInspector();markDirty();toast(`已将 ${memberIds.length} 个节点分组`)}
function toggleSelectedDisabled(){if(mode!=='design'||!selectedIds.size)return;checkpoint();const selectedNodes=nodes.filter(n=>selectedIds.has(n.id)),disable=!selectedNodes.every(n=>n.disabled);selectedNodes.forEach(n=>n.disabled=disable);render();showInspector();markDirty();toast(`${selectedNodes.length} 个节点已${disable?'禁用':'启用'}`)}

function startNodeDrag(e,n){e.preventDefault();const ids=selectedIds.has(n.id)?new Set(selectedIds):new Set([n.id]),moving=nodes.filter(x=>ids.has(x.id)),starts=new Map(moving.map(x=>[x.id,{...x.position}])),start={x:e.clientX,y:e.clientY};checkpoint();ids.forEach(id=>$(`.canvas-node[data-id="${id}"]`)?.classList.add('dragging'));const move=ev=>{const updateStarted=performance.now(),dx=(ev.clientX-start.x)/scale,dy=(ev.clientY-start.y)/scale;moving.forEach(x=>{const p=starts.get(x.id);x.position={x:p.x+dx,y:p.y+dy}});updateNodeElements(ids);updateConnectedEdges(ids);groups.filter(g=>g.memberIds.some(id=>ids.has(id))).forEach(updateGroupElement);scheduleMinimapRender();renderMetrics.lastDragUpdateMs=performance.now()-updateStarted;document.body.dataset.lastDragUpdateMs=renderMetrics.lastDragUpdateMs.toFixed(2)};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);ids.forEach(id=>$(`.canvas-node[data-id="${id}"]`)?.classList.remove('dragging'));renderMinimap();markDirty()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',up)}
function startGroupDrag(e,g){e.preventDefault();const members=nodes.filter(n=>g.memberIds.includes(n.id)),ids=new Set(members.map(n=>n.id)),starts=new Map(members.map(n=>[n.id,{...n.position}])),start={x:e.clientX,y:e.clientY};checkpoint();ids.forEach(id=>$(`.canvas-node[data-id="${id}"]`)?.classList.add('dragging'));const move=ev=>{const dx=(ev.clientX-start.x)/scale,dy=(ev.clientY-start.y)/scale;members.forEach(n=>{const p=starts.get(n.id);n.position={x:p.x+dx,y:p.y+dy}});updateNodeElements(ids);updateConnectedEdges(ids);updateGroupElement(g);scheduleMinimapRender()};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);ids.forEach(id=>$(`.canvas-node[data-id="${id}"]`)?.classList.remove('dragging'));renderMinimap();markDirty()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',up)}
function applyTransform(){const vp=$('#canvas-viewport');$('#world').style.transform=`translate(${pan.x}px,${pan.y}px) scale(${scale})`;if(vp){vp.style.backgroundSize=`${22*scale}px ${22*scale}px`;vp.style.backgroundPosition=`${pan.x}px ${pan.y}px`}$('#zoom-label').textContent=`${Math.round(scale*100)}%`;$('#zoom-reset').textContent=Math.round(scale*100);renderMinimap()}
function graphBounds(){if(!nodes.length)return{x:0,y:0,w:1000,h:700};const pad=160,minX=Math.min(...nodes.map(n=>n.position.x))-pad,minY=Math.min(...nodes.map(n=>n.position.y))-pad,maxX=Math.max(...nodes.map(n=>n.position.x+286))+pad,maxY=Math.max(...nodes.map(n=>n.position.y+260))+pad;return{x:minX,y:minY,w:Math.max(900,maxX-minX),h:Math.max(620,maxY-minY)}}
function renderMinimap(){const map=$('#minimap'),layer=$('#minimap-nodes'),view=$('#minimap-view'),vp=$('#canvas-viewport');if(!map||!layer||!view||!vp)return;const rect=map.getBoundingClientRect(),vr=vp.getBoundingClientRect();if(!rect.width||!rect.height)return;const b=graphBounds(),sx=rect.width/b.w,sy=rect.height/b.h;layer.innerHTML=nodes.map(n=>`<i class="minimap-node" style="left:${(n.position.x-b.x)*sx}px;top:${(n.position.y-b.y)*sy}px;width:${Math.max(3,286*sx)}px;height:${Math.max(3,220*sy)}px"></i>`).join('');const worldLeft=-pan.x/scale,worldTop=-pan.y/scale;view.style.left=`${Math.max(0,(worldLeft-b.x)*sx)}px`;view.style.top=`${Math.max(0,(worldTop-b.y)*sy)}px`;view.style.width=`${Math.min(rect.width,vr.width/scale*sx)}px`;view.style.height=`${Math.min(rect.height,vr.height/scale*sy)}px`;map._bounds=b}
function navigateMinimap(e){const map=$('#minimap'),vp=$('#canvas-viewport'),mr=map.getBoundingClientRect(),vr=vp.getBoundingClientRect(),b=map._bounds||graphBounds();const worldX=b.x+(e.clientX-mr.left)/mr.width*b.w,worldY=b.y+(e.clientY-mr.top)/mr.height*b.h;pan={x:vr.width/2-worldX*scale,y:vr.height/2-worldY*scale};applyTransform()}
function fitView(){if(!nodes.length)return;const box=$('#canvas-viewport').getBoundingClientRect(),minX=Math.min(...nodes.map(n=>n.position.x)),minY=Math.min(...nodes.map(n=>n.position.y)),maxX=Math.max(...nodes.map(n=>n.position.x+286)),maxY=Math.max(...nodes.map(n=>n.position.y+nodeVisualHeight(n.id)));scale=Math.max(.02,Math.min(1,(box.width-120)/(maxX-minX),(box.height-110)/(maxY-minY)));pan={x:(box.width-(minX+maxX)*scale)/2,y:(box.height-(minY+maxY)*scale)/2};applyTransform()}
function autoLayout(){if(mode!=='design')return;checkpoint();const indegree=new Map(nodes.map(n=>[n.id,0])),outgoing=new Map(nodes.map(n=>[n.id,[]])),rank=new Map(nodes.map(n=>[n.id,0]));edges.filter(e=>!e.disabled).forEach(e=>{indegree.set(e.target,(indegree.get(e.target)||0)+1);outgoing.get(e.source)?.push(e.target)});const queue=nodes.filter(n=>indegree.get(n.id)===0).map(n=>n.id);for(let i=0;i<queue.length;i++){const id=queue[i];for(const target of outgoing.get(id)||[]){rank.set(target,Math.max(rank.get(target)||0,(rank.get(id)||0)+1));indegree.set(target,indegree.get(target)-1);if(indegree.get(target)===0)queue.push(target)}}const lanes={};nodes.forEach(n=>(lanes[rank.get(n.id)||0]??=[]).push(n));Object.entries(lanes).forEach(([column,items])=>items.forEach((n,index)=>{n.position={x:100+Number(column)*360,y:70+index*240}}));render();markDirty();setTimeout(fitView,20)}

function startBoxSelection(e){const vp=$('#canvas-viewport'),r=vp.getBoundingClientRect(),box=$('#selection-box');selectionBox={x:e.clientX-r.left,y:e.clientY-r.top,currentX:e.clientX-r.left,currentY:e.clientY-r.top,additive:e.shiftKey||e.metaKey||e.ctrlKey,moved:false};box.hidden=false;updateSelectionBox();const move=ev=>{selectionBox.currentX=ev.clientX-r.left;selectionBox.currentY=ev.clientY-r.top;selectionBox.moved=selectionBox.moved||Math.hypot(selectionBox.currentX-selectionBox.x,selectionBox.currentY-selectionBox.y)>4;updateSelectionBox()};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);const b=selectionBox,ids=b.additive?new Set(selectedIds):new Set();if(b.moved){const left=(Math.min(b.x,b.currentX)-pan.x)/scale,top=(Math.min(b.y,b.currentY)-pan.y)/scale,right=(Math.max(b.x,b.currentX)-pan.x)/scale,bottom=(Math.max(b.y,b.currentY)-pan.y)/scale;nodes.forEach(n=>{if(n.position.x<right&&n.position.x+286>left&&n.position.y<bottom&&n.position.y+220>top)ids.add(n.id)})}else if(!b.additive)ids.clear();selectionBox=null;box.hidden=true;setSelection([...ids]);render();showInspector()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true})}
function updateSelectionBox(){const b=selectionBox,box=$('#selection-box');if(!b)return;box.style.left=`${Math.min(b.x,b.currentX)}px`;box.style.top=`${Math.min(b.y,b.currentY)}px`;box.style.width=`${Math.abs(b.currentX-b.x)}px`;box.style.height=`${Math.abs(b.currentY-b.y)}px`}

function showContext(x,y,type,id){const m=$('#context-menu');m.hidden=false;m.style.left=`${x}px`;m.style.top=`${y}px`;if(type==='multi')m.innerHTML=`<button data-cmd="duplicate-selected">复制 ${selectedIds.size} 个节点 <span>⌘D</span></button><button data-cmd="group">创建分组 <span>G</span></button><button data-cmd="toggle-disabled">启用／禁用 <span>D</span></button><button data-cmd="align">顶端对齐</button><hr><button data-cmd="delete-selected">删除所选 <span>⌫</span></button>`;else if(type==='node')m.innerHTML=`<button data-cmd="inspect">打开配置 <span>↵</span></button><button data-cmd="run-node">运行节点 <span>▶</span></button><button data-cmd="toggle-disabled">启用／禁用 <span>D</span></button><hr><button data-cmd="duplicate">复制节点 <span>⌘D</span></button><button data-cmd="delete">删除节点 <span>⌫</span></button>`;else if(type==='edge')m.innerHTML=`<button data-cmd="inspect">查看数据映射</button><button data-cmd="reconnect-source">重接来源</button><button data-cmd="reconnect-target">重接目标</button><button data-cmd="delete-edge">删除连线</button>`;else m.innerHTML=`<button data-cmd="add">添加节点 <span>/</span></button><button data-cmd="paste">粘贴 <span>⌘V</span></button><hr><button data-cmd="template">载入组合模板</button><button data-cmd="fit">适配全图</button><button data-cmd="shortcuts">快捷键帮助 <span>?</span></button>`;$$('button',m).forEach(b=>b.onclick=()=>{m.hidden=true;const c=b.dataset.cmd;if(c==='inspect'){selectedIds.clear();selected={type,id};inspectorTab=type==='edge'?'mapping':'config';render();showInspector()}if(c==='delete')deleteNode(id);if(c==='duplicate')duplicateNode(id);if(c==='delete-selected')deleteSelectedNodes();if(c==='duplicate-selected')duplicateSelectedNodes();if(c==='group')createGroupFromSelection();if(c==='toggle-disabled')toggleSelectedDisabled();if(c==='align')alignSelectedTop();if(c==='reconnect-source')beginReconnect(id,'source');if(c==='reconnect-target')beginReconnect(id,'target');if(c==='delete-edge'){checkpoint();edges=edges.filter(e=>e.id!==id);clearSelection();render();showInspector()}if(c==='add')openPalette();if(c==='template')$('#template-select').focus();if(c==='fit')fitView();if(c==='shortcuts')$('#shortcut-modal').hidden=false;if(c==='run-node'){setSelection([id]);startRun(true)}})}
function openPalette(){paletteSource=null;const p=$('#palette');p.hidden=false;$('#palette-search').value='';$('#palette-search').placeholder='添加节点或载入模板…';renderPalette();setTimeout(()=>$('#palette-search').focus(),0)}
function openCompatiblePalette(source,point){paletteSource=source;contextPoint=point;pendingPort=null;const p=$('#palette');p.hidden=false;$('#palette-search').value='';$('#palette-search').placeholder=`选择可接收 ${source.port.type} 的节点…`;renderPalette();setTimeout(()=>$('#palette-search').focus(),0)}
function renderPalette(filter=''){const r=$('#palette-results');r.innerHTML='';const list=catalog.definitions.filter(d=>(d.title.includes(filter)||d.id.includes(filter.toLowerCase()))&&(!paletteSource||d.inputs.some(p=>compatible(paletteSource.port.type,p.type))));if(!list.length){r.innerHTML='<div class="tab-empty">没有兼容节点</div>';return}list.forEach(d=>{const targetPort=paletteSource&&d.inputs.find(p=>compatible(paletteSource.port.type,p.type));const b=document.createElement('button');b.innerHTML=`<span>${ICON[d.category]}　${d.title}</span><small>${paletteSource?`连接到 ${targetPort.id}`:`${d.inputs.length} → ${d.outputs.length}`}</small>`;b.onclick=()=>{const source=paletteSource,id=addNode(d.id,contextPoint);$('#palette').hidden=true;paletteSource=null;if(source&&id){const target={nodeId:id,portId:targetPort.id,port:targetPort};connectPorts(source,target)}};r.append(b)})}

function pluginFields(x){return{id:x.id,title:x.title,version:x.version||'0.1.0',description:x.description||'',executorRef:x.executorRef||'',inputs:structuredClone(x.inputs||[]),outputs:structuredClone(x.outputs||[])}}
function initPluginRecords(){const saved=localStorage.getItem(pluginKey);if(saved){try{pluginRecords=JSON.parse(saved)}catch{pluginRecords=[]}}if(!pluginRecords.length)pluginRecords=catalog.definitions.filter(d=>d.source==='plugin').map(d=>({...pluginFields(d),builtin:true,publishedSnapshot:pluginFields(d),skillSource:'',analysis:null,testPayload:'{}',testResult:null,dirty:false}));selectedPluginId=pluginRecords[0]?.id||null;syncPublishedPlugins()}
function persistPlugins(){localStorage.setItem(pluginKey,JSON.stringify(pluginRecords));$('#plugin-save-state').textContent='已保存到本机'}
function syncPublishedPlugins(){const ids=new Set(pluginRecords.map(p=>p.id));catalog.definitions=catalog.definitions.filter(d=>!ids.has(d.id));pluginRecords.filter(p=>p.publishedSnapshot).forEach(p=>catalog.definitions.push({...structuredClone(p.publishedSnapshot),category:'agent',source:'plugin'}))}
function currentPlugin(){return pluginRecords.find(p=>p.id===selectedPluginId)}
function safe(value=''){return String(value).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function openPluginStudio(){if(!pluginRecords.length)newPlugin();$('#plugin-modal').hidden=false;renderPluginStudio()}
function newPlugin(){const id=`plugin.custom-${Date.now().toString(36)}`;pluginRecords.push({id,title:'未命名插件',version:'0.1.0',description:'',executorRef:`plugin://${id.slice(7)}/run@0.1`,inputs:[{id:'prompt',type:'text.prompt',required:true,cardinality:'one'}],outputs:[{id:'artifact',type:'artifact.any',required:true,cardinality:'one'}],skillSource:'',analysis:null,testPayload:'{"prompt":"示例输入"}',testResult:null,publishedSnapshot:null,dirty:true});selectedPluginId=id;pluginEditorTab='definition';persistPlugins();renderPluginStudio()}
function renderPluginStudio(){renderPluginList();const p=currentPlugin(),head=$('#plugin-editor-head'),content=$('#plugin-editor-content');if(!p){head.innerHTML='<b>选择或创建插件</b>';content.innerHTML='';return}head.innerHTML=`<div><b>${safe(p.title)}</b><span>${safe(p.id)} · ${safe(p.version)}</span></div><i class="plugin-status ${p.publishedSnapshot?'published':''}">${p.publishedSnapshot?(p.dirty?'PUBLISHED · 有修改':'PUBLISHED'):'DRAFT'}</i>`;$$('[data-plugin-tab]').forEach(b=>b.classList.toggle('active',b.dataset.pluginTab===pluginEditorTab));if(pluginEditorTab==='definition')renderPluginDefinition(p,content);if(pluginEditorTab==='ports')renderPluginPorts(p,content);if(pluginEditorTab==='skill')renderPluginSkill(p,content);if(pluginEditorTab==='test')renderPluginTest(p,content)}
function renderPluginList(){const root=$('#plugin-list');root.innerHTML='';pluginRecords.forEach(p=>{const b=document.createElement('button');b.className=`plugin-list-item ${p.id===selectedPluginId?'active':''}`;b.innerHTML=`<b>${safe(p.title)}</b><span>${safe(p.id)} · ${p.publishedSnapshot?'已发布':'草稿'}${p.dirty?' · 已修改':''}</span>`;b.onclick=()=>{selectedPluginId=p.id;renderPluginStudio()};root.append(b)})}
function bindPluginFields(p,root){$$('[data-plugin-field]',root).forEach(el=>el.oninput=()=>{p[el.dataset.pluginField]=el.value;if(el.dataset.pluginField==='id')selectedPluginId=el.value;p.dirty=true;renderPluginList();$('#plugin-save-state').textContent='有未保存修改'})}
function renderPluginDefinition(p,root){root.innerHTML=`<div class="plugin-form-grid"><div class="field"><label>插件 ID</label><input data-plugin-field="id" value="${safe(p.id)}" ${p.publishedSnapshot?'readonly':''}></div><div class="field"><label>语义版本</label><input data-plugin-field="version" value="${safe(p.version)}"></div><div class="field"><label>显示名称</label><input data-plugin-field="title" value="${safe(p.title)}"></div><div class="field"><label>Executor Ref</label><input data-plugin-field="executorRef" value="${safe(p.executorRef)}"></div><div class="field full"><label>用途说明</label><textarea data-plugin-field="description">${safe(p.description)}</textarea></div></div><section class="detail-card"><h4>运行边界</h4><p>浏览器只保存插件定义。真实执行必须由受控 Runner 根据 Executor Ref 路由。</p></section>`;bindPluginFields(p,root)}
function portSchemaRow(port,direction,index){return `<div class="port-schema-row" data-port-direction="${direction}" data-port-index="${index}"><input data-port-field="id" value="${safe(port.id)}" placeholder="端口 ID"><select data-port-field="type">${catalog.types.map(t=>`<option ${t===port.type?'selected':''}>${t}</option>`).join('')}</select><select data-port-field="cardinality"><option ${port.cardinality==='one'?'selected':''}>one</option><option ${port.cardinality==='many'?'selected':''}>many</option></select><label><input data-port-field="required" type="checkbox" ${port.required?'checked':''}> 必填</label><button data-remove-port>×</button></div>`}
function renderPluginPorts(p,root){root.innerHTML=`<section><div class="plugin-editor-head"><div><b>输入端口</b><span>定义插件接收的数据类型、基数和必填约束</span></div><button data-add-port="inputs">＋ 输入</button></div><div class="port-schema-list">${p.inputs.map((x,i)=>portSchemaRow(x,'inputs',i)).join('')||'<div class="tab-empty">没有输入端口</div>'}</div></section><section><div class="plugin-editor-head"><div><b>输出端口</b><span>输出将成为可连线和可追溯的 Artifact</span></div><button data-add-port="outputs">＋ 输出</button></div><div class="port-schema-list">${p.outputs.map((x,i)=>portSchemaRow(x,'outputs',i)).join('')||'<div class="tab-empty">没有输出端口</div>'}</div></section>`;$$('[data-add-port]',root).forEach(b=>b.onclick=()=>{p[b.dataset.addPort].push({id:b.dataset.addPort==='inputs'?`input${p.inputs.length+1}`:`output${p.outputs.length+1}`,type:'artifact.any',required:false,cardinality:'one'});p.dirty=true;renderPluginStudio()});$$('.port-schema-row',root).forEach(row=>{const list=p[row.dataset.portDirection],port=list[Number(row.dataset.portIndex)];$$('[data-port-field]',row).forEach(el=>el.onchange=()=>{port[el.dataset.portField]=el.type==='checkbox'?el.checked:el.value;p.dirty=true;renderPluginList()});$('[data-remove-port]',row).onclick=()=>{list.splice(Number(row.dataset.portIndex),1);p.dirty=true;renderPluginStudio()}})}
function analyzeSkillSource(source){const lower=source.toLowerCase(),name=source.match(/^name:\s*(.+)$/mi)?.[1]?.trim()||source.match(/^#\s+(.+)$/m)?.[1]?.trim()||'Skill Adapter',inputs=[];if(/图片|image|图生/.test(lower))inputs.push({id:'images',type:'image.collection',required:true,cardinality:'many'});if(/视频|video/.test(lower))inputs.push({id:'video',type:'video.single',required:false,cardinality:'one'});if(/脚本|script|分镜/.test(lower))inputs.push({id:'script',type:'document.script',required:false,cardinality:'one'});if(/提示词|prompt|文本|text/.test(lower)||!inputs.length)inputs.push({id:'prompt',type:'text.prompt',required:true,cardinality:'one'});const outputType=/视频|video/.test(lower)?'video.collection':/图片|image|图像|分镜/.test(lower)?'image.collection':'artifact.any';return{name,inputs,outputs:[{id:outputType==='video.collection'?'videos':outputType==='image.collection'?'images':'artifact',type:outputType,required:true,cardinality:outputType.endsWith('collection')?'many':'one'}],executorRef:`skill://${name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'adapter'}/run`,signals:[...new Set([...inputs.map(x=>x.type),outputType])],confidence:source.trim().length>80?'high':'medium'}}
function renderPluginSkill(p,root){root.innerHTML=`<div class="skill-layout"><section><b>Skill 源内容</b><textarea id="skill-source" class="skill-source" placeholder="粘贴 SKILL.md 内容…">${safe(p.skillSource||'')}</textarea><button id="analyze-skill" class="primary">分析 Skill</button></section><section><b>转换建议</b><div class="analysis-result">${p.analysis?`名称：${safe(p.analysis.name)}\n执行路由：${safe(p.analysis.executorRef)}\n置信度：${p.analysis.confidence}\n\n输入：\n${p.analysis.inputs.map(x=>`- ${x.id}: ${x.type} (${x.cardinality})`).join('\n')}\n\n输出：\n${p.analysis.outputs.map(x=>`- ${x.id}: ${x.type} (${x.cardinality})`).join('\n')}`:'尚未分析。系统将从 Skill 描述中识别媒体类型、脚本、Prompt、输出和执行路由。'}</div><button id="apply-skill-analysis" ${p.analysis?'':'disabled'}>应用为插件 Schema</button></section></div>`;$('#skill-source').oninput=e=>{p.skillSource=e.target.value;p.dirty=true};$('#analyze-skill').onclick=()=>{p.analysis=analyzeSkillSource(p.skillSource||'');p.dirty=true;renderPluginStudio()};$('#apply-skill-analysis').onclick=()=>{if(!p.analysis)return;p.title=p.analysis.name;p.inputs=structuredClone(p.analysis.inputs);p.outputs=structuredClone(p.analysis.outputs);p.executorRef=p.analysis.executorRef;p.dirty=true;pluginEditorTab='ports';renderPluginStudio();toast('Skill 分析结果已转换为插件端口') }}
function renderPluginTest(p,root){root.innerHTML=`<div class="test-layout"><section><b>模拟输入 JSON</b><textarea id="test-payload" class="test-payload">${safe(p.testPayload||'{}')}</textarea><button id="run-plugin-test" class="primary">运行契约测试</button></section><section><b>测试结果</b><div class="test-result">${p.testResult?safe(JSON.stringify(p.testResult,null,2)):'尚未运行。测试台仅验证 JSON、必填端口和输出收据，不调用真实插件。'}</div><button id="clear-plugin-test">清空结果</button></section></div>`;$('#test-payload').oninput=e=>{p.testPayload=e.target.value};$('#run-plugin-test').onclick=()=>runPluginTest(p);$('#clear-plugin-test').onclick=()=>{p.testResult=null;renderPluginStudio()}}
function runPluginTest(p){let payload;try{payload=JSON.parse(p.testPayload||'{}')}catch(error){p.testResult={status:'FAILED',stage:'parse',message:error.message};return renderPluginStudio()}const missing=p.inputs.filter(x=>x.required&&payload[x.id]===undefined).map(x=>x.id);if(missing.length)p.testResult={status:'BLOCKED',stage:'preflight',missingInputs:missing};else p.testResult={status:'SUCCEEDED',mode:'contract-simulation',executorRef:p.executorRef,outputs:Object.fromEntries(p.outputs.map(x=>[x.id,{type:x.type,artifactId:`fixture://${x.type}/${Date.now().toString(36)}`}]))};persistPlugins();renderPluginStudio()}
function validatePlugin(p){const issues=[];if(!/^plugin\.[a-z0-9][a-z0-9-]*$/.test(p.id))issues.push('插件 ID 必须使用 plugin.xxx 格式');if(!p.title.trim())issues.push('缺少显示名称');if(!p.executorRef.trim())issues.push('缺少 Executor Ref');if(!p.outputs.length)issues.push('至少需要一个输出端口');for(const [label,ports] of [['输入',p.inputs],['输出',p.outputs]]){const ids=ports.map(x=>x.id);if(new Set(ids).size!==ids.length)issues.push(`${label}端口 ID 重复`);if(ids.some(id=>!/^[A-Za-z][A-Za-z0-9_-]*$/.test(id)))issues.push(`${label}端口 ID 格式错误`)}return issues}
function publishPlugin(){const p=currentPlugin();if(!p)return;const issues=validatePlugin(p);if(issues.length)return toast(issues[0],true);p.publishedSnapshot=pluginFields(p);p.dirty=false;syncPublishedPlugins();persistPlugins();renderPluginStudio();if(libraryView==='plugins')renderCatalog($('#node-search').value,true);toast(`插件「${p.title}」已发布到节点库`)}
function duplicatePluginVersion(){const p=currentPlugin();if(!p)return;const copy=structuredClone(p),parts=copy.version.split('.').map(Number);parts[2]=(parts[2]||0)+1;copy.version=parts.join('.');copy.id=`plugin.${p.id.replace(/^plugin\./,'')}-v${parts.join('-')}`;copy.title=`${p.title} 副本`;copy.publishedSnapshot=null;copy.dirty=true;pluginRecords.push(copy);selectedPluginId=copy.id;pluginEditorTab='definition';persistPlugins();renderPluginStudio()}

function workflowFromTemplate(w){return{title:w.title,nodes:structuredClone(w.nodes),edges:structuredClone(w.edges),groups:[],pluginDependencies:[],savedAt:new Date().toISOString()}}
function createPerformanceFixture(count){const fixtureNodes=[],fixtureEdges=[],pairs=Math.max(1,Math.floor(count/2));for(let i=0;i<pairs;i++){const row=Math.floor(i/10),column=i%10,promptId=`bench-prompt-${i}`,generateId=`bench-generate-${i}`;fixtureNodes.push({id:promptId,definitionId:'content.prompt',position:{x:column*720,y:row*520},config:{}},{id:generateId,definitionId:'generate.text-to-image',position:{x:column*720+340,y:row*520},config:{}});fixtureEdges.push({id:`bench-edge-${i}`,source:promptId,sourcePort:'prompt',target:generateId,targetPort:'prompt'})}return{title:`性能夹具 · ${fixtureNodes.length} 节点`,nodes:fixtureNodes,edges:fixtureEdges,groups:[],pluginDependencies:[],savedAt:new Date().toISOString()}}
function hydrateWorkflow(snap){const source=snap||workflowFromTemplate(examples.workflows[0]);nodes=structuredClone(source.nodes||[]);edges=structuredClone(source.edges||[]);groups=structuredClone(source.groups||[]);$('#workflow-title').textContent=source.title||'未命名工作流';clearSelection();history=[];future=[];runSession=null;clearTimeout(runTimer);$('#run-drawer').classList.remove('open');dirty=false;$('#save-state').textContent='已保存';$('#save-state').classList.remove('dirty')}
function normalizeProject(p){const now=new Date().toISOString();return{...p,createdAt:p.createdAt||now,updatedAt:p.updatedAt||now,draft:p.draft||null,versions:Array.isArray(p.versions)?p.versions:[],runs:Array.isArray(p.runs)?p.runs:[]}}
function initProjects(){let migrated=false,saved=localStorage.getItem(projectKey);if(!saved){saved=localStorage.getItem(legacyProjectKey);migrated=Boolean(saved)}if(saved){try{projectRecords=JSON.parse(saved).map(normalizeProject)}catch{projectRecords=[]}}if(!projectRecords.length)projectRecords=[normalizeProject({id:'project-demo',title:'实验工程',description:'多模态节点工作流交互工程'})];const remembered=localStorage.getItem(activeProjectKey);selectedProjectId=projectRecords.some(p=>p.id===remembered)?remembered:projectRecords[0].id;const active=currentProject();if(migrated&&!active.draft){try{const legacy=JSON.parse(localStorage.getItem(legacyCanvasKey));if(Array.isArray(legacy?.nodes)&&Array.isArray(legacy?.edges))active.draft={title:legacy.title||'迁移草稿',nodes:legacy.nodes,edges:legacy.edges,groups:legacy.groups||[],pluginDependencies:[],savedAt:new Date().toISOString()}}catch{}}if(!active.draft)active.draft=workflowFromTemplate(examples.workflows[0]);persistProjects()}
function currentProject(){return projectRecords.find(p=>p.id===selectedProjectId)}
function persistProjects(){localStorage.setItem(projectKey,JSON.stringify(projectRecords));localStorage.setItem(activeProjectKey,selectedProjectId);updateProjectHeader()}
function updateProjectHeader(){const p=currentProject();if(!p)return;$('#project-title').textContent=p.title;$('#version-badge').textContent=p.versions?.length?`草稿 · v${p.versions.length+1}`:'草稿'}
function captureWorkflow(){return{title:$('#workflow-title').textContent,nodes:structuredClone(nodes),edges:structuredClone(edges),groups:structuredClone(groups),pluginDependencies:collectPluginDependencies(),savedAt:new Date().toISOString()}}
function collectPluginDependencies(){return dependenciesForNodes(nodes)}
function persistCurrentDraft(){const p=currentProject();if(!p)return;p.draft=captureWorkflow();p.updatedAt=new Date().toISOString();persistProjects();dirty=false;$('#save-state').textContent='已保存';$('#save-state').classList.remove('dirty')}
function saveProjectDraft(){clearTimeout(markDirty.t);persistCurrentDraft();toast('工程草稿已保存')}
function publishWorkflowVersion(){const p=currentProject();if(!p)return;const issues=validateGraph({requirePluginDependencies:true});if(issues.length)return toast(`${issues[0].code} · ${issues[0].message}`,true);const snap=captureWorkflow(),version={id:`wv-${Date.now().toString(36)}`,number:(p.versions?.length||0)+1,status:'PUBLISHED',publishedAt:new Date().toISOString(),...snap};p.versions??=[];p.versions.unshift(version);p.draft=snap;p.updatedAt=version.publishedAt;persistProjects();$('#version-badge').textContent=`v${version.number}`;renderWorkspace();toast(`工作流 v${version.number} 已发布`)}
function restoreWorkflowSnapshot(snap,label='版本'){if(!snap)return;checkpoint();nodes=structuredClone(snap.nodes||[]);edges=structuredClone(snap.edges||[]);groups=structuredClone(snap.groups||[]);$('#workflow-title').textContent=snap.title||'恢复版本';clearSelection();render();markDirty();$('#workspace-modal').hidden=true;toast(`已从${label}恢复为新草稿`)}
function newProject(){clearTimeout(markDirty.t);persistCurrentDraft();const id=`project-${Date.now().toString(36)}`,now=new Date().toISOString(),draft=workflowFromTemplate(examples.workflows[0]);projectRecords.push({id,title:`新工程 ${projectRecords.length+1}`,description:'',createdAt:now,updatedAt:now,draft,versions:[],runs:[]});selectedProjectId=id;hydrateWorkflow(draft);persistProjects();render();setTimeout(fitView,20);renderWorkspace();}
function switchProject(id){if(id===selectedProjectId)return;clearTimeout(markDirty.t);persistCurrentDraft();const target=projectRecords.find(p=>p.id===id);if(!target)return;selectedProjectId=id;if(!target.draft)target.draft=workflowFromTemplate(examples.workflows[0]);hydrateWorkflow(target.draft);persistProjects();render();setTimeout(fitView,20);$('#workspace-modal').hidden=false;renderWorkspace()}
function openWorkspace(){saveProjectDraft();$('#workspace-modal').hidden=false;renderWorkspace()}
function renderWorkspace(){renderProjectList();$$('[data-workspace-tab]').forEach(b=>b.classList.toggle('active',b.dataset.workspaceTab===workspaceTab));const root=$('#workspace-content'),p=currentProject();if(!p)return;if(workspaceTab==='overview')renderWorkspaceOverview(root,p);if(workspaceTab==='versions')renderWorkspaceVersions(root,p);if(workspaceTab==='runs')renderWorkspaceRuns(root,p);if(workspaceTab==='dependencies')renderWorkspaceDependencies(root,p);if(workspaceTab==='transfer')renderWorkspaceTransfer(root,p)}
function renderProjectList(){const root=$('#project-list');root.innerHTML='';projectRecords.forEach(p=>{const b=document.createElement('button');b.className=`project-card ${p.id===selectedProjectId?'active':''}`;b.innerHTML=`<b>${safe(p.title)}</b><small>${p.versions?.length||0} 版本 · ${p.runs?.length||0} 运行</small>`;b.onclick=()=>switchProject(p.id);root.append(b)})}
function renderWorkspaceOverview(root,p){root.innerHTML=`<div class="workspace-actions"><button id="save-project-draft">保存当前草稿</button><button id="publish-workflow" class="primary">发布工作流版本</button><button id="open-current-canvas">返回画布</button></div><div class="workspace-summary"><div><small>草稿节点</small><b>${nodes.length}</b></div><div><small>已发布版本</small><b>${p.versions?.length||0}</b></div><div><small>运行记录</small><b>${p.runs?.length||0}</b></div><div><small>插件依赖</small><b>${collectPluginDependencies().length}</b></div></div><div class="plugin-form-grid"><div class="field"><label>工程名称</label><input id="project-name" value="${safe(p.title)}"></div><div class="field"><label>工程 ID</label><input value="${safe(p.id)}" readonly></div><div class="field full"><label>工程说明</label><textarea id="project-description">${safe(p.description||'')}</textarea></div></div>`;$('#save-project-draft').onclick=saveProjectDraft;$('#publish-workflow').onclick=publishWorkflowVersion;$('#open-current-canvas').onclick=()=>$('#workspace-modal').hidden=true;$('#project-name').onchange=e=>{p.title=e.target.value||'未命名工程';persistProjects();renderWorkspace()};$('#project-description').onchange=e=>{p.description=e.target.value;persistProjects()}}
function renderWorkspaceVersions(root,p){root.innerHTML=`<div class="workspace-actions"><button id="publish-version-here" class="primary">发布当前草稿</button></div><div class="version-list">${p.versions?.length?p.versions.map(v=>`<div class="version-row"><div><b>工作流 v${v.number}</b><small>${safe(v.title)} · ${v.nodes.length} 节点</small></div><span>${v.status}</span><small>${new Date(v.publishedAt).toLocaleString()}</small><button data-restore-version="${v.id}">恢复为草稿</button></div>`).join(''):'<div class="tab-empty">尚未发布工作流版本</div>'}</div>`;$('#publish-version-here').onclick=publishWorkflowVersion;$$('[data-restore-version]',root).forEach(b=>b.onclick=()=>restoreWorkflowSnapshot(p.versions.find(v=>v.id===b.dataset.restoreVersion),'发布版本'))}
function renderWorkspaceRuns(root,p){root.innerHTML=`<div class="history-list">${p.runs?.length?p.runs.map(r=>`<div class="history-row"><div><b>${safe(r.runId)}</b><small>${safe(r.workflowTitle||'工作流')}</small></div><span>${r.status}</span><small>${new Date(r.finishedAt||r.createdAt).toLocaleString()}</small><button data-view-run="${r.runId}">查看收据</button></div>`).join(''):'<div class="tab-empty">尚无已归档运行</div>'}</div>`;$$('[data-view-run]',root).forEach(b=>b.onclick=()=>{const r=p.runs.find(x=>x.runId===b.dataset.viewRun);$('#artifact-title').textContent=`运行收据 ${r.runId}`;$('#artifact-meta').textContent=`${r.status} · ${r.workflowTitle}`;$('#artifact-content').innerHTML=`<pre class="receipt-view">${safe(JSON.stringify(r,null,2))}</pre>`;$('#artifact-modal').hidden=false})}
function renderWorkspaceDependencies(root,p){const deps=collectPluginDependencies();root.innerHTML=`<section class="detail-card"><h4>当前草稿依赖锁</h4><p>发布版本时固定插件 NodeDefinition 版本与 Executor Ref，避免后续插件升级改变历史行为。</p></section><div class="dependency-list">${deps.length?deps.map(d=>`<div class="dependency-row"><div><b>${safe(d.definitionId)}</b><small>NodeDefinition</small></div><span>v${safe(d.version)}</span><small>${safe(d.executorRef)}</small><button data-open-plugin-dep="${d.definitionId}">打开插件</button></div>`).join(''):'<div class="tab-empty">当前工作流没有插件依赖</div>'}</div>`;$$('[data-open-plugin-dep]',root).forEach(b=>b.onclick=()=>{selectedPluginId=b.dataset.openPluginDep;$('#workspace-modal').hidden=true;openPluginStudio()})}
function renderWorkspaceTransfer(root,p){const payload=JSON.stringify({format:'multimodal-workflow@0.8',project:{id:p.id,title:p.title},workflow:captureWorkflow()},null,2);root.innerHTML=`<div class="transfer-layout"><section><b>导出工作流 JSON</b><textarea id="export-json" class="transfer-json" readonly>${safe(payload)}</textarea><button id="download-json">下载 JSON</button></section><section><b>导入工作流 JSON</b><textarea id="import-json" class="transfer-json" placeholder="粘贴 multimodal-workflow JSON…"></textarea><button id="import-workflow" class="primary">校验并导入为草稿</button></section></div>`;$('#download-json').onclick=()=>{const blob=new Blob([payload],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${p.id}-workflow.json`;a.click();URL.revokeObjectURL(a.href);toast('工作流 JSON 已导出')};$('#import-workflow').onclick=()=>{let data;try{data=JSON.parse($('#import-json').value)}catch(error){return toast(`JSON 格式错误：${error.message}`,true)}if(!['multimodal-workflow@0.7','multimodal-workflow@0.8'].includes(data.format)||!Array.isArray(data.workflow?.nodes)||!Array.isArray(data.workflow?.edges))return toast('不是有效的 V0.7/V0.8 工作流文件',true);const imported={...data.workflow,pluginDependencies:data.workflow.pluginDependencies||dependenciesForNodes(data.workflow.nodes)},issues=GraphCore.validateWorkflow(catalog,imported,{requirePluginDependencies:true});if(issues.length)return toast(`${issues[0].code} · ${issues[0].message}`,true);restoreWorkflowSnapshot(imported,'导入文件');p.draft=captureWorkflow();persistProjects()}}

function dependenciesForNodes(items){return(items||[]).map(n=>def(n.definitionId)).filter(d=>d?.source==='plugin').map(d=>({definitionId:d.id,version:d.version,executorRef:d.executorRef})).filter((x,i,a)=>a.findIndex(y=>y.definitionId===x.definitionId)===i)}
function validationWorkflow(){return{title:$('#workflow-title').textContent,nodes,edges,groups,pluginDependencies:dependenciesForNodes(nodes)}}
function validateGraph(options={}){return GraphCore.validateWorkflow(catalog,validationWorkflow(),options)}
function startRunLegacy(single=false){const issues=validateGraph();$('#run-drawer').classList.add('open');$('#run-title').textContent=single?'节点运行预检':'工作流运行预检';if(issues.length){$('#run-summary').textContent=`${issues.length} 项阻塞`;$('#run-content').innerHTML=`<div class="run-grid"><section><small>拓扑</small><b>BLOCKED</b></section><section><small>阻塞问题</small><b>${issues.length}</b></section><section><small>真实模型</small><b>未连接</b></section><section><small>执行范围</small><b>${single?'1 节点':'完整图'}</b></section></div><div class="detail-card"><h4>预检问题</h4>${issues.map(x=>`<p>⚠ ${x.code} · ${x.message}</p>`).join('')}</div>`;return}$('#run-summary').textContent='预检通过 · 模拟运行';$('#run-dot').classList.add('running');let progress=0;$('#run-content').innerHTML=`<div class="run-grid"><section><small>Workflow</small><b>已冻结</b></section><section><small>节点</small><b>${single?1:nodes.length}</b></section><section><small>端口契约</small><b>PASS</b></section><section><small>执行器</small><b>模拟</b></section></div><div class="detail-card"><h4>运行进度</h4><div class="progress"><i id="progress-bar" style="width:0%"></i></div><p id="progress-copy">创建模拟 NodeRun…</p></div>`;const timer=setInterval(()=>{progress+=20;$('#progress-bar').style.width=`${progress}%`;$('#progress-copy').textContent=progress<100?`验证输入快照与节点契约 · ${progress}%`:'模拟运行完成 · 进入审阅模式';if(progress>=100){clearInterval(timer);$('#run-dot').classList.remove('running');$('#run-summary').textContent='SUCCEEDED · 仅交互模拟';setMode('review')}},350)}

function scopeLabel(scope){return({full:'完整工作流',selected:'所选节点',upstream:'运行到此',downstream:'从此运行'})[scope]||scope}
function resolveRunNodeIds(scope){const seeds=selectedIds.size?[...selectedIds]:selected?.type==='node'?[selected.id]:[];if(scope==='full'||!seeds.length)return nodes.map(n=>n.id);const result=new Set(seeds),queue=[...seeds];while(queue.length){const id=queue.shift();const linked=scope==='upstream'?edges.filter(e=>e.target===id).map(e=>e.source):scope==='downstream'?edges.filter(e=>e.source===id).map(e=>e.target):[];linked.forEach(next=>{if(!result.has(next)){result.add(next);queue.push(next)}})}return nodes.filter(n=>result.has(n.id)).map(n=>n.id)}
function topoRunOrder(ids){const set=new Set(ids),degree=new Map(ids.map(id=>[id,0])),out=new Map(ids.map(id=>[id,[]]));edges.filter(e=>!e.disabled&&set.has(e.source)&&set.has(e.target)).forEach(e=>{degree.set(e.target,degree.get(e.target)+1);out.get(e.source).push(e.target)});const queue=ids.filter(id=>degree.get(id)===0),ordered=[];while(queue.length){const id=queue.shift();ordered.push(id);for(const next of out.get(id)||[]){degree.set(next,degree.get(next)-1);if(degree.get(next)===0)queue.push(next)}}return ordered.length===ids.length?ordered:ids}
function validateRunScope(ids){const scope=new Set(ids),edgeIds=new Set(edges.filter(e=>scope.has(e.source)||scope.has(e.target)).map(e=>e.id));return validateGraph({requirePluginDependencies:true}).filter(x=>!x.nodeId&&!x.edgeId||x.nodeId&&scope.has(x.nodeId)||x.edgeId&&edgeIds.has(x.edgeId)).map(x=>({...x,kind:x.code}))}
function startRun(single=false){const scope=single?'selected':'full',ids=topoRunOrder(resolveRunNodeIds(scope)),issues=validateRunScope(ids);clearTimeout(runTimer);runSession={id:`run-${Date.now().toString(36)}`,scope,status:issues.length?'BLOCKED':'PREPARED',createdAt:new Date().toISOString(),nodeIds:ids,failureNodeId:null,issues,events:[],receipt:null,nodeRuns:ids.map(id=>{const n=nodes.find(x=>x.id===id);return{nodeId:id,status:n?.disabled?'skipped':'queued',startedAt:null,finishedAt:null,artifacts:[],error:null}})};activeRunTab=issues.length?'issues':'overview';$('#run-drawer').classList.add('open');renderRunDrawer()}
function addRunEvent(type,nodeId,message){runSession.events.push({time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),type,nodeId,message})}
function renderRunDrawer(){if(!runSession)return;$$('[data-run-tab]').forEach(b=>b.classList.toggle('active',b.dataset.runTab===activeRunTab));$('#run-title').textContent=`运行 ${runSession.id.slice(-7)}`;$('#run-summary').textContent=`${runSession.status} · ${scopeLabel(runSession.scope)}`;$('#run-dot').classList.toggle('running',runSession.status==='RUNNING');const root=$('#run-content');if(activeRunTab==='overview')renderRunOverview(root);if(activeRunTab==='nodes')renderRunNodes(root);if(activeRunTab==='events')renderRunEvents(root);if(activeRunTab==='io')renderRunIO(root);if(activeRunTab==='issues')renderRunIssues(root);if(activeRunTab==='receipts')renderRunReceipts(root)}
function renderRunOverview(root){const completed=runSession.nodeRuns.filter(x=>['succeeded','skipped'].includes(x.status)).length,total=runSession.nodeRuns.length,progress=total?Math.round(completed/total*100):0,canStart=runSession.status==='PREPARED',hasSeed=selectedIds.size>0||selected?.type==='node';root.innerHTML=`<div class="run-preflight"><div><div class="run-grid"><section><small>运行状态</small><b>${runSession.status}</b></section><section><small>执行范围</small><b>${scopeLabel(runSession.scope)}</b></section><section><small>节点</small><b>${total}</b></section><section><small>预检问题</small><b>${runSession.issues.length}</b></section></div><section class="detail-card"><h4>${canStart?'运行前快照':'运行进度'}</h4><div class="progress"><i style="width:${progress}%"></i></div><p>${completed}/${total} 个节点已完成或跳过 · WorkflowVersion 已冻结为本地快照</p></section></div><div class="run-controls"><label>运行范围<select id="run-scope-select" ${runSession.status==='RUNNING'?'disabled':''}><option value="full" ${runSession.scope==='full'?'selected':''}>完整工作流</option><option value="selected" ${runSession.scope==='selected'?'selected':''} ${hasSeed?'':'disabled'}>所选节点</option><option value="upstream" ${runSession.scope==='upstream'?'selected':''} ${hasSeed?'':'disabled'}>运行到此（含上游）</option><option value="downstream" ${runSession.scope==='downstream'?'selected':''} ${hasSeed?'':'disabled'}>从此运行（含下游）</option></select></label><label>故障演练<select id="failure-node" ${!canStart?'disabled':''}><option value="">不注入故障</option>${runSession.nodeRuns.filter(x=>x.status!=='skipped').map(x=>`<option value="${x.nodeId}" ${runSession.failureNodeId===x.nodeId?'selected':''}>${safe(def(nodes.find(n=>n.id===x.nodeId).definitionId).title)}</option>`).join('')}</select></label><button id="execute-run" class="primary" ${canStart?'':'disabled'}>创建并执行模拟运行</button><button id="open-run-nodes">查看节点状态</button></div></div>`;$('#run-scope-select').onchange=e=>{const scope=e.target.value,ids=topoRunOrder(resolveRunNodeIds(scope)),issues=validateRunScope(ids);runSession.scope=scope;runSession.nodeIds=ids;runSession.issues=issues;runSession.status=issues.length?'BLOCKED':'PREPARED';runSession.nodeRuns=ids.map(id=>({nodeId:id,status:nodes.find(n=>n.id===id)?.disabled?'skipped':'queued',startedAt:null,finishedAt:null,artifacts:[],error:null}));renderRunDrawer()};$('#failure-node').onchange=e=>runSession.failureNodeId=e.target.value||null;$('#execute-run').onclick=executePreparedRun;$('#open-run-nodes').onclick=()=>{activeRunTab='nodes';renderRunDrawer()}}
function executePreparedRun(){if(!runSession||runSession.status!=='PREPARED')return;runSession.status='RUNNING';addRunEvent('WorkflowRun','',`创建运行，范围：${scopeLabel(runSession.scope)}`);runSession.nodeRuns.filter(x=>x.status==='skipped').forEach(x=>addRunEvent('NodeRun',x.nodeId,'节点已禁用，跳过执行'));renderRunDrawer();runNextNode()}
function runNextNode(){if(!runSession||runSession.status!=='RUNNING')return;const current=runSession.nodeRuns.find(x=>x.status==='queued');if(!current)return completeRun();current.status='running';current.startedAt=new Date().toISOString();addRunEvent('NodeRun',current.nodeId,'RUNNING · 输入快照已冻结');renderRunDrawer();runTimer=setTimeout(()=>{if(runSession.failureNodeId===current.nodeId){current.status='failed';current.finishedAt=new Date().toISOString();current.error='模拟执行器超时';runSession.nodeRuns.filter(x=>x.status==='queued').forEach(x=>x.status='blocked');runSession.status='FAILED';runSession.issues.push({kind:'node-failure',nodeId:current.nodeId,message:`${def(nodes.find(n=>n.id===current.nodeId).definitionId).title}：模拟执行器超时`});addRunEvent('NodeRun',current.nodeId,'FAILED · 模拟执行器超时');renderRunDrawer();return}current.status='succeeded';current.finishedAt=new Date().toISOString();current.artifacts=createMockArtifacts(current.nodeId);addRunEvent('Artifact',current.nodeId,`SUCCEEDED · 产生 ${current.artifacts.length} 个 Artifact`);renderRunDrawer();runNextNode()},420)}
function createMockArtifacts(nodeId){const n=nodes.find(x=>x.id===nodeId),d=def(n.definitionId);return d.outputs.map((p,i)=>({id:`artifact-${nodeId}-${p.id}-${Date.now().toString(36)}`,portId:p.id,type:p.type,createdAt:new Date().toISOString(),previews:p.type.startsWith('image')?PREVIEWS.slice(0,p.cardinality==='many'?4:1):[],content:p.type==='document.script'?'S01  京都清晨街道\n柠萌背着旅行包走入画面。\n\nS02  町屋门前\n角色停下并看向镜头。':null,index:i}))}
function completeRun(){runSession.status='SUCCEEDED';runSession.receipt={runId:runSession.id,status:'SUCCEEDED',scope:runSession.scope,workflowTitle:$('#workflow-title').textContent,workflowVersion:currentProject()?.versions?.[0]?.number||'draft',pluginDependencies:collectPluginDependencies(),createdAt:runSession.createdAt,finishedAt:new Date().toISOString(),nodeRuns:runSession.nodeRuns.map(x=>({nodeId:x.nodeId,status:x.status,artifactIds:x.artifacts.map(a=>a.id)})),eventCount:runSession.events.length};addRunEvent('WorkflowRun','',`SUCCEEDED · ${runSession.nodeRuns.length} 个节点已结算`);const p=currentProject();if(p){p.runs??=[];p.runs.unshift(structuredClone(runSession.receipt));p.updatedAt=runSession.receipt.finishedAt;persistProjects()}$('#run-dot').classList.remove('running');renderRunDrawer()}
function retryNodeRun(nodeId){const failed=runSession.nodeRuns.find(x=>x.nodeId===nodeId);if(!failed)return;failed.status='queued';failed.error=null;runSession.nodeRuns.filter(x=>x.status==='blocked').forEach(x=>x.status='queued');runSession.issues=runSession.issues.filter(x=>x.kind!=='node-failure');runSession.failureNodeId=null;runSession.status='RUNNING';addRunEvent('Retry',nodeId,'创建修复尝试，复用冻结输入快照');activeRunTab='nodes';renderRunDrawer();runNextNode()}
function renderRunNodes(root){root.innerHTML=`<div class="run-node-list">${runSession.nodeRuns.map(x=>{const n=nodes.find(n=>n.id===x.nodeId),d=n&&def(n.definitionId),detail=x.error||(x.artifacts.length?`${x.artifacts.length} artifacts`:x.status==='succeeded'?'已完成 · 无输出端口':x.status==='skipped'?'节点已禁用':'等待执行');return `<div class="run-node-row"><i class="status-dot ${x.status}"></i><div><b>${safe(d?.title||x.nodeId)}</b><small>${safe(x.nodeId)}</small></div><span class="run-status">${x.status}</span><small>${detail}</small><div>${x.status==='failed'?`<button data-retry-node="${x.nodeId}">重试</button>`:''}${x.artifacts.length?`<button data-view-artifact="${x.nodeId}">查看产物</button>`:''}</div></div>`}).join('')}</div>`;$$('[data-retry-node]',root).forEach(b=>b.onclick=()=>retryNodeRun(b.dataset.retryNode));$$('[data-view-artifact]',root).forEach(b=>b.onclick=()=>openArtifactViewer(b.dataset.viewArtifact))}
function renderRunEvents(root){root.innerHTML=runSession.events.length?`<div class="run-event-list">${[...runSession.events].reverse().map(e=>`<div class="event-row"><small>${e.time}</small><b>${e.type}</b><span>${e.nodeId?`${safe(e.nodeId)} · `:''}${safe(e.message)}</span></div>`).join('')}</div>`:'<div class="run-empty"><b>尚无运行事件</b><span>执行后将记录 NodeRun、Artifact、Retry 与 WorkflowRun 事件。</span></div>'}
function renderRunIO(root){root.innerHTML=`<div class="snapshot-list">${runSession.nodeRuns.map(x=>{const n=nodes.find(n=>n.id===x.nodeId),d=def(n.definitionId),incoming=edges.filter(e=>e.target===x.nodeId);return `<div class="snapshot-card"><div><b>${safe(d.title)}</b><small>${safe(x.nodeId)} · ${x.status}</small></div><div><small>冻结输入</small>${d.inputs.map(p=>{const e=incoming.find(e=>e.targetPort===p.id);return `<code>${p.id}: ${e?`${e.source}.${e.sourcePort}`:n.config?.[p.id]!==undefined?'常量配置':'未提供'}</code>`}).join('')||'<code>无输入</code>'}</div><div><small>输出 Artifact</small>${x.artifacts.map(a=>`<code>${a.portId}: ${a.type}</code>`).join('')||d.outputs.map(p=>`<code>${p.id}: 等待生成</code>`).join('')||'<code>无输出端口</code>'}</div></div>`}).join('')}</div>`}
function renderRunIssues(root){root.innerHTML=runSession.issues.length?`<div class="detail-card"><h4>${runSession.issues.length} 项问题</h4>${runSession.issues.map(x=>`<p>⚠ ${safe(x.message)}</p>`).join('')}</div>`:'<div class="run-empty"><b>没有阻塞问题</b><span>拓扑、输入快照和执行器路由均通过本地预检。</span></div>'}
function renderRunReceipts(root){const value=runSession.receipt||{runId:runSession.id,status:runSession.status,scope:runSession.scope,message:'运行完成后生成最终收据'};root.innerHTML=`<pre class="receipt-view">${safe(JSON.stringify(value,null,2))}</pre>`}
function openArtifactViewer(nodeId){const nr=runSession?.nodeRuns.find(x=>x.nodeId===nodeId),n=nodes.find(x=>x.id===nodeId),d=n&&def(n.definitionId);if(!nr?.artifacts.length)return toast('该节点尚无可查看产物',true);const root=$('#artifact-content'),images=nr.artifacts.filter(a=>a.type.startsWith('image')),videos=nr.artifacts.filter(a=>a.type.startsWith('video')),documents=nr.artifacts.filter(a=>a.type.startsWith('document')||a.type.startsWith('text'));$('#artifact-title').textContent=`${d.title} · ${nr.artifacts.length} 个产物`;$('#artifact-meta').textContent=`NodeRun ${nodeId} · ${nr.status.toUpperCase()}`;if(images.length)root.innerHTML=`<div class="artifact-gallery">${images.flatMap(a=>(a.previews.length?a.previews:PREVIEWS.slice(0,1)).map((src,i)=>`<figure><img src="${src}"><figcaption>${a.portId} · 候选 ${i+1} · ${a.type}</figcaption></figure>`)).join('')}</div>`;else if(videos.length)root.innerHTML=`<div class="artifact-video"><button>▶</button><span>${videos[0].type} · 本地预览占位</span></div>`;else if(documents.length)root.innerHTML=`<pre class="artifact-document">${safe(documents[0].content||'本地文档产物')}</pre>`;else root.innerHTML=`<pre class="receipt-view">${safe(JSON.stringify(nr.artifacts,null,2))}</pre>`;$('#artifact-modal').hidden=false}

function renderAssets(){const roles=['角色参考','地点参考','室内场景','构图参考','服装参考','首帧','尾帧','动作参考','角色参考','地点参考'];const grid=$('#asset-grid');roles.forEach((role,i)=>{const b=document.createElement('button');b.className='asset-card';b.dataset.assetRef=`fixture://asset/${i+1}`;b.dataset.assetRole=role;b.innerHTML=`<img src="${PREVIEWS[i%4]}"><div><b>${role} ${String(i+1).padStart(2,'0')}</b><small>${role} · 2048×1536</small></div>`;b.onclick=()=>{b.classList.toggle('selected');updateAssetCount()};grid.append(b)})}
function updateAssetCount(){$('#asset-selected').textContent=`已选择 ${$$('.asset-card.selected').length} 项`}
function openAssets(){if(selected?.type!=='node')return toast('请先选择一个节点',true);assetTargetNodeId=selected.id;const n=nodes.find(x=>x.id===assetTargetNodeId),refs=new Set(n.config.assetRefs||[]);$$('.asset-card').forEach(card=>card.classList.toggle('selected',refs.has(card.dataset.assetRef)));updateAssetCount();$('#asset-modal').hidden=false}
function setMode(next){mode=next;$$('.mode-switch button').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#app').className=`app mode-${mode}`;$('#run').textContent=mode==='design'?'预检并运行':mode==='run'?'运行当前版本':'创建修复草稿';if(mode==='run')$('#run-drawer').classList.add('open');toast(`已切换到${mode==='design'?'设计':mode==='run'?'运行':'审阅'}模式`)}

function bindUI(){
  $('#open-workspace').onclick=openWorkspace;$$('[data-close-workspace]').forEach(b=>b.onclick=()=>$('#workspace-modal').hidden=true);$('#new-project').onclick=newProject;$$('[data-workspace-tab]').forEach(b=>b.onclick=()=>{workspaceTab=b.dataset.workspaceTab;renderWorkspace()});$('#node-search').oninput=e=>libraryView==='templates'?renderTemplateCards():renderCatalog(e.target.value,libraryView==='plugins');$$('[data-library-view]').forEach(b=>b.onclick=()=>setLibraryView(b.dataset.libraryView));$('#load-template').onclick=()=>loadWorkflow(examples.workflows.find(w=>w.id===$('#template-select').value));$('#open-plugin-studio').onclick=openPluginStudio;$$('[data-close-plugins]').forEach(b=>b.onclick=()=>$('#plugin-modal').hidden=true);$('#new-plugin').onclick=newPlugin;$$('[data-plugin-tab]').forEach(b=>b.onclick=()=>{pluginEditorTab=b.dataset.pluginTab;renderPluginStudio()});$('#save-plugin').onclick=()=>{persistPlugins();renderPluginStudio();toast('插件草稿已保存')};$('#publish-plugin').onclick=publishPlugin;$('#duplicate-plugin').onclick=duplicatePluginVersion;$('#add-node').onclick=openPalette;$('#empty-add-node').onclick=openPalette;$('#toggle-library').onclick=()=>$('#app').classList.toggle('library-hidden');$('#collapse-left').onclick=()=>$('#app').classList.add('library-hidden');$('#auto-layout').onclick=autoLayout;$('#fit-view').onclick=fitView;$('#shortcut-help').onclick=()=>$('#shortcut-modal').hidden=false;$('#validate').onclick=()=>{const e=validateGraph();toast(e.length?`${e[0].code} · ${e[0].message}`:'画布检查通过',!!e.length);if(e.length)startRun()};$('#run').onclick=()=>mode==='review'?setMode('design'):startRun();$('#close-drawer').onclick=()=>$('#run-drawer').classList.remove('open');$$('[data-run-tab]').forEach(b=>b.onclick=()=>{activeRunTab=b.dataset.runTab;if(runSession)renderRunDrawer()});$$('[data-close-artifact]').forEach(b=>b.onclick=()=>$('#artifact-modal').hidden=true);
  $$('.mode-switch button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#undo').onclick=()=>{if(!history.length)return;future.push(snapshot());restore(history.pop())};$('#redo').onclick=()=>{if(!future.length)return;history.push(snapshot());restore(future.pop())};$('#zoom-in').onclick=()=>{scale=Math.min(1.6,scale+.1);applyTransform()};$('#zoom-out').onclick=()=>{scale=Math.max(.05,scale-.1);applyTransform()};$('#zoom-reset').onclick=()=>{scale=1;applyTransform()};
  const vp=$('#canvas-viewport');vp.ondragover=e=>e.preventDefault();vp.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('definitionId');if(id){const r=vp.getBoundingClientRect();addNode(id,{x:(e.clientX-r.left-pan.x)/scale,y:(e.clientY-r.top-pan.y)/scale})}};vp.oncontextmenu=e=>{if(e.target.closest('.canvas-node')||e.target.closest('.edge'))return;e.preventDefault();const r=vp.getBoundingClientRect();contextPoint={x:(e.clientX-r.left-pan.x)/scale,y:(e.clientY-r.top-pan.y)/scale};showContext(e.clientX,e.clientY,'canvas')};vp.ondblclick=e=>{if(mode==='design'&&!e.target.closest('.canvas-node,.edge,button,.minimap')){const r=vp.getBoundingClientRect();contextPoint={x:(e.clientX-r.left-pan.x)/scale,y:(e.clientY-r.top-pan.y)/scale};openPalette()}};vp.onwheel=e=>{e.preventDefault();const old=scale;scale=Math.max(.05,Math.min(1.6,scale*(e.deltaY>0?.92:1.08)));const r=vp.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top;pan.x=mx-(mx-pan.x)*(scale/old);pan.y=my-(my-pan.y)*(scale/old);applyTransform()};
  let panning=null;vp.onpointerdown=e=>{if(e.target.closest('.canvas-node,.edge,button,.minimap'))return;if(e.button===1||e.altKey){panning={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};return}if(e.button===0)startBoxSelection(e)};window.addEventListener('pointermove',e=>{if(panning){pan={x:panning.px+e.clientX-panning.x,y:panning.py+e.clientY-panning.y};applyTransform()}});window.addEventListener('pointerup',()=>panning=null);const minimap=$('#minimap');minimap.onpointerdown=e=>{e.preventDefault();navigateMinimap(e);const move=ev=>navigateMinimap(ev),up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true})};
  $('#palette-search').oninput=e=>renderPalette(e.target.value);$$('[data-close-modal]').forEach(x=>x.onclick=()=>{$('#asset-modal').hidden=true;assetTargetNodeId=null});$$('[data-close-shortcuts]').forEach(x=>x.onclick=()=>$('#shortcut-modal').hidden=true);$('#bind-assets').onclick=()=>{const cards=$$('.asset-card.selected');if(!cards.length)return toast('请先选择资产',true);const n=nodes.find(x=>x.id===assetTargetNodeId);if(!n)return toast('目标节点已不存在',true);checkpoint();n.config.assetRefs=cards.map(c=>c.dataset.assetRef);n.config.assetRoles=cards.map(c=>({ref:c.dataset.assetRef,role:c.dataset.assetRole}));$('#asset-modal').hidden=true;assetTargetNodeId=null;render();showInspector();toast(`已绑定 ${cards.length} 项资产到「${def(n.definitionId).title}」`)};
  document.onkeydown=e=>{const typing=e.target.matches('input,textarea,select');if(e.key==='Escape'){$('#palette').hidden=true;$('#context-menu').hidden=true;$('#shortcut-modal').hidden=true;$('#plugin-modal').hidden=true;$('#artifact-modal').hidden=true;$('#workspace-modal').hidden=true;pendingPort=null;connectionDrag=null;reconnectEdge=null;paletteSource=null;render()}if(e.key==='/'&&!typing){e.preventDefault();openPalette()}if(e.key==='?'&&!typing)$('#shortcut-modal').hidden=false;if((e.metaKey||e.ctrlKey)&&e.key==='z'){e.preventDefault();e.shiftKey?$('#redo').click():$('#undo').click()}if((e.metaKey||e.ctrlKey)&&e.key==='s'){e.preventDefault();saveProjectDraft()}if((e.metaKey||e.ctrlKey)&&e.key==='d'&&selectedIds.size&&!typing){e.preventDefault();duplicateSelectedNodes()}if(!e.metaKey&&!e.ctrlKey&&!e.altKey&&!typing&&e.key.toLowerCase()==='f')fitView();if(!e.metaKey&&!e.ctrlKey&&!e.altKey&&!typing&&e.key.toLowerCase()==='l')autoLayout();if(!e.metaKey&&!e.ctrlKey&&!e.altKey&&!typing&&e.key.toLowerCase()==='g')createGroupFromSelection();if(!e.metaKey&&!e.ctrlKey&&!e.altKey&&!typing&&e.key.toLowerCase()==='d')toggleSelectedDisabled();if((e.key==='Delete'||e.key==='Backspace')&&selectedIds.size&&!typing)deleteSelectedNodes()};
  document.onclick=e=>{if(!e.target.closest('#context-menu'))$('#context-menu').hidden=true};window.onbeforeunload=()=>dirty?'画布存在未保存修改':undefined;
}
boot().catch(error=>{console.error(error);toast(`Harness 加载失败：${error.message}`,true)});
